/* Generated by dev/gen-statsui.js from src/stats-app.html. Do not edit by hand. */
module.exports = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Pseudo CEO stats</title>\n<style>\n:root{--bg:#F6F5F1;--sheet:#fff;--ink:#14161B;--muted:#5C6270;--faint:#8A90A0;--rule:#DAD8D0;--accent:#0B4FB3;--gain:#14794A;--loss:#B3261E;--bar:#0B4FB3;--bar2:#9DB8E6}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#0E1117;--sheet:#161B24;--ink:#EEF0F5;--muted:#A3A9B8;--faint:#7C8396;--rule:#2A3140;--accent:#7FB0FF;--gain:#4CC38A;--loss:#FF8A80;--bar:#7FB0FF;--bar2:#2D4470}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\n.wrap{max-width:980px;margin:0 auto;padding:28px 16px 64px;display:grid;gap:28px}\nh1{font-size:28px;margin:0;letter-spacing:-.01em}\nh2{font-size:17px;margin:0 0 10px}\np{margin:0;color:var(--muted)}\n.row{display:flex;flex-wrap:wrap;gap:10px;align-items:center}\ninput,select,button{font:inherit;color:inherit}\ninput,select{padding:9px 11px;border:1px solid var(--rule);border-radius:6px;background:var(--sheet)}\nbutton{padding:9px 15px;border-radius:6px;border:0;background:var(--accent);color:#fff;font-weight:600;cursor:pointer}\nbutton.sec{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--rule)}\nbutton.danger{background:transparent;color:var(--loss);box-shadow:inset 0 0 0 1px var(--loss);padding:4px 10px;font-size:13px}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}\n.tile{background:var(--sheet);border-radius:8px;padding:14px 16px}\n.tile b{display:block;font-size:30px;line-height:1.1;font-variant-numeric:tabular-nums}\n.tile span{font-size:13px;color:var(--muted)}\n.card{background:var(--sheet);border-radius:8px;padding:16px;overflow-x:auto}\ntable{width:100%;border-collapse:collapse;font-size:14.5px;font-variant-numeric:tabular-nums}\nth,td{padding:8px 10px;border-bottom:1px solid var(--rule);text-align:right;white-space:nowrap}\nth:first-child,td:first-child{text-align:left}\nth{font-size:12.5px;color:var(--muted);font-weight:600}\ntr:last-child td{border-bottom:0}\n.up{color:var(--gain)}.down{color:var(--loss)}\nsvg{display:block;width:100%;height:auto}\n.legend{display:flex;gap:16px;font-size:13px;color:var(--muted);margin-top:8px}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:6px}\n.err{color:var(--loss)}\n.spark{display:inline-flex;align-items:flex-end;gap:2px;height:26px}\n.spark i{display:block;width:8px;background:var(--bar);border-radius:1px 1px 0 0;min-height:1px}\n[hidden]{display:none!important}\n</style>\n</head>\n<body>\n<main class=\"wrap\">\n  <div><h1>Pseudo CEO stats</h1><p>Play counts, leaderboard moderation and the contact list. Private.</p></div>\n  <form class=\"row\" id=\"gate\">\n    <select id=\"days\" aria-label=\"Range\"><option value=\"7\">Last 7 days</option><option value=\"30\" selected>Last 30 days</option><option value=\"90\">Last 90 days</option></select>\n    <button>Load</button><button class=\"sec\" id=\"out-btn\" type=\"button\">Sign out</button><span id=\"msg\" class=\"err\"></span>\n  </form>\n  <div id=\"out\" hidden>\n    <div class=\"tiles\" id=\"tiles\"></div>\n    <section style=\"margin-top:28px\"><h2>Unique players and games started, per day</h2><div class=\"card\"><svg id=\"chart\" viewBox=\"0 0 900 220\" role=\"img\" aria-label=\"Daily unique players and games started\"></svg><div class=\"legend\"><span><i style=\"background:var(--bar)\"></i>Unique players</span><span><i style=\"background:var(--bar2)\"></i>Games started</span></div></div></section>\n    <section style=\"margin-top:28px\"><h2>By company and seat</h2><div class=\"card\"><table id=\"grid\"></table></div><p style=\"margin-top:8px;font-size:13px\">Counts since tracking began, not just the range above. Avg edge is points ahead of the real playbook on completed games.</p></section>\n    <section style=\"margin-top:28px\"><h2>Where games end</h2><div class=\"card\"><table id=\"drop\"></table></div><p style=\"margin-top:8px;font-size:13px\">How many games reached each quarter. A steep early drop means players quit before the game finds its feet.</p></section>\n    <section style=\"margin-top:28px\"><h2>Moderation</h2>\n      <div class=\"row\"><select id=\"mco\"></select><select id=\"md\"><option value=\"easy\">Guided</option><option value=\"medium\">Standard</option><option value=\"hard\">Hot Seat</option></select><button class=\"sec\" id=\"mload\" type=\"button\">Load board</button></div>\n      <div class=\"card\" style=\"margin-top:10px\"><table id=\"mod\"></table></div>\n    </section>\n    <section style=\"margin-top:28px\"><h2>Players</h2>\n      <p style=\"font-size:13px;margin:0 0 8px\">People who left an email after a game, having read that the site owner may write to them about his work. Every row agreed to that. The Updates column shows who also ticked the box for new companies and features. Write to people one at a time from your own address, keep it short, and remove anyone who asks.</p>\n      <div class=\"row\"><button class=\"sec\" id=\"pload\" type=\"button\">Load players</button><label style=\"display:flex;gap:6px;align-items:center;font-size:14px\"><input type=\"checkbox\" id=\"ponly\"> Ticked updates only</label><label style=\"display:flex;gap:6px;align-items:center;font-size:14px\"><input type=\"checkbox\" id=\"pwork\"> Work emails only</label><button class=\"sec\" id=\"pcsv\" type=\"button\">Download CSV</button></div>\n      <div class=\"card\" style=\"margin-top:10px;overflow-x:auto\"><table id=\"players\"></table></div>\n    </section>\n  </div>\n</main>\n<script>\nconst CO={intc:'Intel',ba:'Boeing',unh:'UnitedHealth',nke:'Nike',khc:'Kraft Heinz'},DF={easy:'Guided',medium:'Standard',hard:'Hot Seat'};\nconst $=id=>document.getElementById(id),n=v=>(v||0).toLocaleString('en-US');\nlet KEY='';try{KEY=sessionStorage.getItem('pc.key')||''}catch(e){}\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(path,opt){const r=await fetch(path,Object.assign({headers:{'X-Stats-Key':KEY}},opt));const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||('Error '+r.status));return j}\n$('gate').addEventListener('submit',e=>{e.preventDefault();load()});\n$('out-btn').onclick=()=>{try{sessionStorage.removeItem('pc.key')}catch(e){}location.reload()};\nasync function load(){\n  $('msg').textContent='';\n  try{const s=await api('/api/stats?days='+$('days').value);render(s);$('out').hidden=false}\n  catch(e){$('msg').textContent=e.message;$('out').hidden=true}\n}\nfunction render(s){\n  const T=s.total,starts=T.start||0;let done=0,fired=0;\n  for(const c in CO)for(const d in DF){done+=T['done:'+c+':'+d]||0;fired+=T['fired:'+c+':'+d]||0}\n  const ended=done+fired;\n  $('tiles').innerHTML=[[n(s.uvAll),'unique players, all time'],[n(starts),'games started'],[ended?Math.round(ended/Math.max(starts,1)*100)+'%':'0%','games that reached the debrief'],[n(done),'completed'],[n(fired),'fired by the board'],[n(T.share),'shares'],[n(T.post),'leaderboard posts'],[n(T.view),'page views']].map(x=>'<div class=\"tile\"><b>'+x[0]+'</b><span>'+x[1]+'</span></div>').join('');\n  // daily chart\n  const W=900,H=220,pad=28,ser=s.series,mx=Math.max(1,...ser.map(d=>Math.max(d.uv,d.ev.start||0))),bw=(W-pad*2)/ser.length;\n  let g='<line x1=\"'+pad+'\" y1=\"'+(H-pad)+'\" x2=\"'+(W-pad)+'\" y2=\"'+(H-pad)+'\" stroke=\"var(--rule)\"/>';\n  ser.forEach((d,i)=>{const x=pad+i*bw,h1=(H-pad*2)*(d.ev.start||0)/mx,h2=(H-pad*2)*d.uv/mx;\n    g+='<rect x=\"'+(x+bw*.12)+'\" y=\"'+(H-pad-h1)+'\" width=\"'+bw*.76+'\" height=\"'+h1+'\" fill=\"var(--bar2)\"><title>'+d.day+': '+(d.ev.start||0)+' started</title></rect>';\n    g+='<rect x=\"'+(x+bw*.3)+'\" y=\"'+(H-pad-h2)+'\" width=\"'+bw*.4+'\" height=\"'+h2+'\" fill=\"var(--bar)\"><title>'+d.day+': '+d.uv+' unique players</title></rect>';});\n  g+='<text x=\"'+pad+'\" y=\"'+(H-8)+'\" font-size=\"12\" fill=\"var(--faint)\">'+ser[0].day+'</text><text x=\"'+(W-pad)+'\" y=\"'+(H-8)+'\" font-size=\"12\" text-anchor=\"end\" fill=\"var(--faint)\">'+ser[ser.length-1].day+'</text><text x=\"'+pad+'\" y=\"14\" font-size=\"12\" fill=\"var(--faint)\">max '+mx+'</text>';\n  $('chart').innerHTML=g;\n  // grid\n  let t='<thead><tr><th>Company and difficulty</th><th>Started</th><th>Completed</th><th>Fired</th><th>Finish rate</th><th>Avg edge</th><th>Ranked entries</th></tr></thead><tbody>';\n  for(const c in CO)for(const d in DF){const k=c+':'+d,st=T['start:'+k]||0,dn=T['done:'+k]||0,fr=T['fired:'+k]||0,en=T['edgeN:'+k]||0,ed=en?(T['edge:'+k]||0)/en/10:null;\n    t+='<tr><td>'+CO[c]+', '+DF[d]+'</td><td>'+n(st)+'</td><td>'+n(dn)+'</td><td>'+n(fr)+'</td><td>'+(st?Math.round((dn+fr)/st*100)+'%':'–')+'</td><td class=\"'+(ed==null?'':ed>=0?'up':'down')+'\">'+(ed==null?'–':(ed>=0?'+':'−')+Math.abs(ed).toFixed(1))+'</td><td>'+n(s.boards[k])+'</td></tr>'}\n  $('grid').innerHTML=t+'</tbody>';\n  // drop-off\n  let dr='<thead><tr><th>Company and difficulty</th><th>Quarters reached</th></tr></thead><tbody>';\n  for(const c in CO)for(const d in DF){const q=[];for(let i=0;i<20;i++)q.push(T['q:'+c+':'+d+':'+i]||0);const top=Math.max(...q);\n    if(!top){dr+='<tr><td>'+CO[c]+', '+DF[d]+'</td><td class=\"faint\" style=\"text-align:left\">no games yet</td></tr>';continue}\n    const last=q.map((v,i)=>v?i:-1).reduce((a,b)=>Math.max(a,b));\n    dr+='<tr><td>'+CO[c]+', '+DF[d]+'</td><td style=\"text-align:left\"><span class=\"spark\">'+q.slice(0,last+1).map((v,i)=>'<i style=\"height:'+Math.max(3,Math.round(26*v/top))+'px\" title=\"Quarter '+(i+1)+': '+v+'\"></i>').join('')+'</span> <span class=\"faint\" style=\"margin-left:6px\">'+q[0]+' to '+q[last]+'</span></td></tr>'}\n  $('drop').innerHTML=dr+'</tbody>';\n}\n$('mco').innerHTML=Object.entries(CO).map(([k,v])=>'<option value=\"'+k+'\">'+v+'</option>').join('');\n$('mload').onclick=modLoad;\nasync function modLoad(){\n  try{const j=await api('/api/admin?co='+$('mco').value+'&d='+$('md').value);\n    $('mod').innerHTML=j.rows.length?'<thead><tr><th>Name</th><th>Edge</th><th>Scenario</th><th>Posted</th><th></th></tr></thead><tbody>'+j.rows.map(r=>'<tr><td>'+esc(r.n)+'</td><td>'+(r.edge>=0?'+':'−')+Math.abs(r.edge).toFixed(1)+'</td><td>'+esc(r.seed)+'</td><td>'+new Date(r.ts).toLocaleDateString()+'</td><td><button class=\"danger\" data-k=\"'+r.k+'\">Remove</button></td></tr>').join('')+'</tbody>':'<tbody><tr><td class=\"faint\">No entries on this board.</td></tr></tbody>'}\n  catch(e){$('msg').textContent=e.message}\n}\n$('mod').addEventListener('click',async e=>{const b=e.target.closest('button[data-k]');if(!b||!confirm('Remove this entry from the leaderboard?'))return;\n  try{await api('/api/admin',{method:'POST',headers:{'X-Stats-Key':KEY,'Content-Type':'application/json'},body:JSON.stringify({co:$('mco').value,d:$('md').value,k:b.dataset.k})});modLoad()}catch(er){$('msg').textContent=er.message}});\nconst FREE=/^(gmail|googlemail|yahoo|ymail|hotmail|outlook|live|msn|icloud|me|mac|aol|proton|protonmail|pm|gmx|mail|zoho|comcast|att|verizon|sbcglobal|bellsouth|cox)\\./i;\nlet PLAYERS=[];\nfunction renderPlayers(){\n  const only=$('ponly').checked,work=$('pwork').checked;\n  const dom=e=>String(e).split('@')[1]||'';\n  const rows=PLAYERS.filter(r=>(!only||r.u)&&(!work||!FREE.test(dom(r.e))));\n  $('players').innerHTML=rows.length?'<thead><tr><th>Name</th><th>Email</th><th>Updates</th><th>Games</th><th>First game</th><th>Last seen</th></tr></thead><tbody>'+rows.map(r=>{const w=!FREE.test(dom(r.e));return '<tr><td>'+esc(r.n)+'</td><td><a href=\"mailto:'+esc(r.e)+'\">'+esc(r.e)+'</a>'+(w?' <b title=\"Not a common personal email provider\" style=\"color:var(--bar)\">work</b>':'')+'</td><td>'+(r.u?'yes':'no')+'</td><td>'+n(r.times||1)+'</td><td>'+esc((CO[r.co]||'')+(r.d?', '+(DF[r.d]||r.d):''))+'</td><td>'+new Date(r.last||r.ts||0).toLocaleDateString()+'</td></tr>'}).join('')+'</tbody>':'<tbody><tr><td class=\"faint\">No players match.</td></tr></tbody>';\n}\n$('pload').onclick=async()=>{try{const j=await api('/api/leads');PLAYERS=j.rows||[];renderPlayers();$('pload').textContent='Reload players ('+j.total+')'}catch(e){$('msg').textContent=e.message}};\n$('ponly').onchange=$('pwork').onchange=renderPlayers;\n$('pcsv').onclick=async()=>{try{const r=await fetch('/api/leads?format=csv',{headers:{'X-Stats-Key':KEY}});if(!r.ok)throw new Error((await r.json().catch(()=>({}))).error||('Error '+r.status));const b=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='pseudo-ceo-players.csv';document.body.appendChild(a);a.click();a.remove()}catch(e){$('msg').textContent=e.message}};\nif(KEY)load();\n</script>\n</body>\n</html>\n";
